#include "../src/shell.hpp"
#include <filesystem>
#include <fstream>
#include <cassert>
#include <chrono>
#include <iostream>
namespace fs=std::filesystem;
void put(const fs::path&p,const std::string&s){std::ofstream(p,std::ios::binary)<<s;}
std::string get(const fs::path&p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
int main(){auto root=fs::absolute(fs::path("build")/("profile-test-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())));auto old=root/"private",console=root/"console",profile=console/"WinBrew/Users/Default";fs::create_directories(old/"Desktop/.winbrew-trash/box");fs::create_directories(old/"Documents/nested");fs::create_directory(console);put(old/"Desktop/Note.txt","Owner text\r\n");put(old/"Documents/nested/report.txt","Report");put(old/"Desktop/.winbrew-trash/box/deleted.txt","Recoverable");put(old/"steam-secret","DO NOT MIGRATE");put(console/"game-files","DO NOT MODIFY");
auto s=std::make_unique<ww::Shell>();assert(s->init("assets",nullptr,nullptr,nullptr,(old/"settings.ini").string().c_str()));assert(s->configure_console_storage(console.string().c_str(),profile.string().c_str()));assert(s->file_user_root()==profile.string()&&s->file_c_root()==console.string());assert(get(profile/"Desktop/Note.txt")=="Owner text\r\n"&&get(profile/"Desktop/.winbrew-trash/box/deleted.txt")=="Recoverable");assert(fs::exists(old/"Desktop/Note.txt")&&!fs::exists(profile/"steam-secret")&&get(console/"game-files")=="DO NOT MODIFY");for(auto name:{"Desktop","Documents","Downloads","Pictures","Music","Videos"})assert(fs::is_directory(profile/name));char desktop[1024];s->desktop_folder(desktop,sizeof(desktop));assert(desktop==(profile/"Desktop").string());s->file_location_open(402);s->draw();assert(std::string(s->file_path)==console.string()&&s->file_drives.size()==1&&s->file_drives[0].letter=="C:");assert(s->file_friendly_path((profile/"Desktop").string().c_str())=="C:\\WinBrew\\Users\\Default\\Desktop");s->file_location_open(430);assert(std::string(s->file_path)==(profile/"Desktop").string());s->file_browser_action(2102);s->insert_text("C:\\WinBrew\\Users\\Default\\Documents");s->file_address_submit();assert(std::string(s->file_path)==(profile/"Documents").string());
// Existing verified profile remains authoritative after edits/restart.
put(profile/"Desktop/Note.txt","New version");auto again=std::make_unique<ww::Shell>();assert(again->init("assets",nullptr,nullptr,nullptr,(old/"settings.ini").string().c_str()));assert(again->configure_console_storage(console.string().c_str(),profile.string().c_str()));assert(get(profile/"Desktop/Note.txt")=="New version");
again->window=0;again->new_document(1421);assert(again->window==4&&std::string(again->document.path).find((profile/"Desktop").string()+"/")==0);again->insert_text("Saved on large C");assert(again->document.save());assert(get(again->document.path)=="Saved on large C");again->document.close(true);again->window=1;again->file_location_open(420);again->draw();bool console_root=false;for(const auto&nav:again->file_nav)if(nav.label=="Console Root"&&nav.path=="/")console_root=true;assert(console_root);again->file_location_open(424);assert(std::string(again->file_path)=="/"&&again->file_current_label()=="Console Root");
// Unknown destinations, symlink sources and unfinished stages fail without replacement.
std::string why;auto conflict=console/"conflict";fs::create_directory(conflict);put(conflict/"keep.txt","Keep");assert(!ww::fileops::prepare_user_profile(old.string().c_str(),console.string().c_str(),conflict.string().c_str(),why)&&get(conflict/"keep.txt")=="Keep");auto staged=console/"stage";fs::create_directory(staged.string()+".migrating-v1");assert(!ww::fileops::prepare_user_profile(old.string().c_str(),console.string().c_str(),staged.string().c_str(),why));fs::create_symlink(console/"game-files",old/"Documents/link.txt");assert(!ww::fileops::prepare_user_profile(old.string().c_str(),console.string().c_str(),(console/"linked").string().c_str(),why)&&!fs::exists(console/"linked"));assert(get(console/"game-files")=="DO NOT MODIFY"&&get(old/"Desktop/Note.txt")=="Owner text\r\n");assert(root.parent_path()==fs::absolute("build"));fs::remove_all(root);std::cout<<"PASS: verified personal profile/recovery copy, originals retained, internal/game exclusion, C aliases/known folders, restart edits, conflict/stage/link refusal\n";}
